class Solution {
    struct State {
        int d;
        string path;
        int r, c;
        bool operator>(const State& o) const {
            if (d != o.d) return d > o.d;
            return path > o.path;
        }
    };
public:
    string findShortestWay(vector<vector<int>>& maze, vector<int>& ball, vector<int>& hole) {
        int m = maze.size(), n = maze[0].size();
        priority_queue<State, vector<State>, greater<State>> pq;
        vector<vector<pair<int, string>>> dist(m, vector<pair<int, string>>(n, {INT_MAX, ""}));

        pq.push({0, "", ball[0], ball[1]});
        dist[ball[0]][ball[1]] = {0, ""};

        vector<tuple<int, int, char>> dirs = {{1, 0, 'd'}, {0, -1, 'l'}, {0, 1, 'r'}, {-1, 0, 'u'}};

        while (!pq.empty()) {
            auto [d, path, r, c] = pq.top();
            pq.pop();
            if (r == hole[0] && c == hole[1]) return path;
            if (make_pair(d, path) > dist[r][c]) continue;

            for (auto [dr, dc, move] : dirs) {
                int nr = r, nc = c, step = 0;
                while (nr + dr >= 0 && nr + dr < m && nc + dc >= 0 && nc + dc < n && maze[nr + dr][nc + dc] == 0) {
                    nr += dr;
                    nc += dc;
                    step++;
                    if (nr == hole[0] && nc == hole[1]) break;
                }
                pair<int, string> cand = {d + step, path + move};
                if (cand < dist[nr][nc]) {
                    dist[nr][nc] = cand;
                    pq.push({cand.first, cand.second, nr, nc});
                }
            }
        }
        return "impossible";
    }
};

class Solution {
    static class State implements Comparable<State> {
        int d;
        String path;
        int r, c;
        State(int d, String path, int r, int c) {
            this.d = d;
            this.path = path;
            this.r = r;
            this.c = c;
        }
        public int compareTo(State o) {
            if (this.d != o.d) return Integer.compare(this.d, o.d);
            return this.path.compareTo(o.path);
        }
    }

    public String findShortestWay(int[][] maze, int[] ball, int[] hole) {
        int m = maze.length, n = maze[0].length;
        PriorityQueue<State> pq = new PriorityQueue<>();
        int[][] dist = new int[m][n];
        String[][] pathMap = new String[m][n];
        for (int i = 0; i < m; i++) {
            Arrays.fill(dist[i], Integer.MAX_VALUE);
        }

        pq.offer(new State(0, "", ball[0], ball[1]));
        dist[ball[0]][ball[1]] = 0;
        pathMap[ball[0]][ball[1]] = "";

        int[][] dirs = {{1, 0}, {0, -1}, {0, 1}, {-1, 0}};
        char[] moves = {'d', 'l', 'r', 'u'};

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            if (cur.r == hole[0] && cur.c == hole[1]) return cur.path;
            if (cur.d > dist[cur.r][cur.c] || (cur.d == dist[cur.r][cur.c] && cur.path.compareTo(pathMap[cur.r][cur.c]) > 0)) {
                continue;
            }

            for (int i = 0; i < 4; i++) {
                int nr = cur.r, nc = cur.c, step = 0;
                while (nr + dirs[i][0] >= 0 && nr + dirs[i][0] < m && nc + dirs[i][1] >= 0 && nc + dirs[i][1] < n && maze[nr + dirs[i][0]][nc + dirs[i][1]] == 0) {
                    nr += dirs[i][0];
                    nc += dirs[i][1];
                    step++;
                    if (nr == hole[0] && nc == hole[1]) break;
                }
                int newD = cur.d + step;
                String newPath = cur.path + moves[i];
                if (newD < dist[nr][nc] || (newD == dist[nr][nc] && newPath.compareTo(pathMap[nr][nc]) < 0)) {
                    dist[nr][nc] = newD;
                    pathMap[nr][nc] = newPath;
                    pq.offer(new State(newD, newPath, nr, nc));
                }
            }
        }
        return "impossible";
    }
}

var findShortestWay = function(maze, ball, hole) {
    const m = maze.length, n = maze[0].length;
    const dist = Array.from({ length: m }, () => new Array(n).fill(Infinity));
    const pathMap = Array.from({ length: m }, () => new Array(n).fill(""));

    const dirs = [[1, 0, "d"], [0, -1, "l"], [0, 1, "r"], [-1, 0, "u"]];
    const queue = [[0, "", ball[0], ball[1]]];
    dist[ball[0]][ball[1]] = 0;
    pathMap[ball[0]][ball[1]] = "";

    while (queue.length > 0) {
        queue.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : (a[1] < b[1] ? -1 : 1));
        const [d, path, r, c] = queue.shift();
        if (r === hole[0] && c === hole[1]) return path;
        if (d > dist[r][c] || (d === dist[r][c] && path > pathMap[r][c])) continue;

        for (const [dr, dc, move] of dirs) {
            let nr = r, nc = c, step = 0;
            while (nr + dr >= 0 && nr + dr < m && nc + dc >= 0 && nc + dc < n && maze[nr + dr][nc + dc] === 0) {
                nr += dr;
                nc += dc;
                step++;
                if (nr === hole[0] && nc === hole[1]) break;
            }
            const newD = d + step;
            const newPath = path + move;
            if (newD < dist[nr][nc] || (newD === dist[nr][nc] && newPath < pathMap[nr][nc])) {
                dist[nr][nc] = newD;
                pathMap[nr][nc] = newPath;
                queue.push([newD, newPath, nr, nc]);
            }
        }
    }
    return "impossible";
};
